<template>
  <layout-make-media
    :main-title="t('textToVideoTitle')"
    :example-title="t('videoResolutionUpscaleExamples')"
  >
    <!-- 左上区域：视频分辨率提升配置面板 -->
    <template #left-top>
      <VideoResolutionUpscalePanel
        @generate-success="handleGenerateSuccess"
        @generate-error="handleGenerateError"
        @generate-create="handleGenerateCreate"
        @loading="handleLoading"
      />
    </template>

    <!-- 右上区域：结果展示区域 -->
    <template #right-top>
      <div class="result-panel">
        <media-generate-result 
          :media-type="MEDIA_TYPES.VIDEO" 
          :operation-type="VIDEO_OPERATIONS.UPSCALE"
          :result-state="currentState" 
          :media-data="resultMediaData" 
          :estimatedTime="estimatedTime"
          :error-message="errorMessage"
          @action="handleAction"
          @retry="handleRetry">
        </media-generate-result>
      </div>
    </template>

    <!-- 底部区域：示例展示 -->
    <template #bottom>
      <bottom-image-video :comType="EXAMPLE_TYPES.VIDEO" />
    </template>
  </layout-make-media>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { ElMessage } from 'element-plus';
import { useI18n } from 'vue-i18n';
import LayoutMakeMedia from '@/components/layout/media-make.vue';
import VideoResolutionUpscalePanel from './panel/left-panel.vue';
import LImg from '@/components/l-img.vue';
import MediaGenerateResult from '@/components/business/media-generate-result.vue';
import { MEDIA_TYPES, VIDEO_OPERATIONS } from '@/types/media-tool';
import { handleMediaAction } from '@/utils/dialogMethod/media-action-handler.js';
import { downloadVideo } from '@/utils/util.js';
import BottomImageVideo from "@/components/produce-media/image-video.vue";
import { EXAMPLE_TYPES } from "@/types/common.js";
import { routerTo } from '@/router/navigation.js';
import { ROUTER_PATHS } from '@/router/constants.js';
import { useMediaGenerationStore } from '@/store/modules/media-generation';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 状态管理
const generatedResult = ref(null);
const isGenerating = ref(false);
const estimatedTime = ref(null);
const errorMessage = ref('');
const layoutMakeMedia = ref(null);

// 结果状态管理
const currentState = ref('empty'); // 'empty', 'loading', 'success', 'error'
const resultMediaData = ref({});

// 处理生成成功
const handleGenerateSuccess = (result) => {
  console.log('Video resolution upscale generated successfully:', result);
  generatedResult.value = result;
  currentState.value = 'success';
  resultMediaData.value = {
    url: result.videoUrl || 'https://www.w3schools.com/html/mov_bbb.mp4',
    seed: result.seed
  };
  isGenerating.value = false;
};

// 处理生成错误
const handleGenerateError = (error) => {
  console.error('Video resolution upscale generation failed:', error);
  currentState.value = 'error';
  errorMessage.value = error.message || t('generateFailed');
  isGenerating.value = false;
  ElMessage.error(t('generateFailed'));
};

// 开始生成
const handleGenerateCreate = () => {
  console.log('Start generating video resolution upscale');
  currentState.value = 'loading';
  isGenerating.value = true;
  layoutMakeMedia.value?.scrollTo({
    top: 0,
    behavior: 'smooth'
  });
};
const handleLoading = (loading,time) => {
  isGenerating.value = loading;
  estimatedTime.value = time;
  
};

// 处理操作事件
const handleAction = (action) => {
  console.log('handleAction:', action);
  
  // 使用通用的媒体操作处理器
  handleMediaAction(action, resultMediaData.value, {
    onConfirm: (actionType, result) => {
      mediaStore.setGenerationResult(actionType, { videoUrl: result?.data?.url || '' });
      // TODO 临时拦截，后续接口未完成 yangjie
      if (actionType != VIDEO_OPERATIONS.DOWNLOAD) { 
        ElMessage.warning('Unsupported Operation !!!');
        return;
      }
      switch (actionType) {
        case VIDEO_OPERATIONS.DOWNLOAD:
          handleDownloadVideo(resultMediaData.value);
          break;
        case VIDEO_OPERATIONS.UPSCALE:
          // 继续放大 - 刷新当前页面数据
          ElMessage.success(t('upscaleCompleted'));
          break;
        case VIDEO_OPERATIONS.SOUNDTRACK:
          // 视频配乐 - 跳转到视频配乐页面
          routerTo(ROUTER_PATHS.VIDEO_TO_SOUNDTRACK, {
            videoUrl: resultMediaData.value.url,
            seed: resultMediaData.value.seed,
            source: 'video-upscaler'
          });
          break;
        case VIDEO_OPERATIONS.FRAME_FILLING:
          // 视频帧填充 - 跳转到视频帧填充页面
          routerTo(ROUTER_PATHS.VIDEO_FRAME_FILLING, {
            videoUrl: resultMediaData.value.url,
            seed: resultMediaData.value.seed,
            source: 'video-upscaler'
          });
          break;
        case VIDEO_OPERATIONS.VIDEO_STYLE:
          // 视频风格转换 - 跳转到视频风格转换页面
          routerTo(ROUTER_PATHS.VIDEO_STYLE_TRANSFER, {
            videoUrl: resultMediaData.value.url,
            seed: resultMediaData.value.seed,
            source: 'video-upscaler'
          });
          break;
        default:
          console.warn('Unknown action type:', actionType);
          break;
      }
    },
    onCancel: (actionType, result) => {
      console.log(`${actionType} operation cancelled:`, result);
    }
  });
};

// 处理重试事件
const handleRetry = () => {
  currentState.value = 'empty';
  errorMessage.value = '';
  generatedResult.value = null;
  resultMediaData.value = {};
};

// 下载视频功能实现
const handleDownloadVideo = async (mediaData) => {
  if (!mediaData?.url) {
    ElMessage.warning(t('noVideoToDownload'));
    return;
  }

  try {
    await downloadVideo(mediaData.url);
  } catch (error) {
    console.error('Download failed:', error);
  }
};

// 组件挂载时初始化
onMounted(() => {
  layoutMakeMedia.value = document.querySelector('.layout-make-media');
});
</script>

